        private static readonly System.Collections.Generic.HashSet<string> AllSet = new(All, System.StringComparer.OrdinalIgnoreCase);

        /// <summary>Determines whether the specified identifier is a registered member of <see cref="Blocks"/>.</summary>
        public static bool IsValid(string? identifier)
        {
            if (string.IsNullOrWhiteSpace(identifier)) return false;
            int bracket = identifier.IndexOf('[');
            if (bracket >= 0) identifier = identifier[..bracket].Trim();
            if (!identifier.Contains(':')) identifier = "minecraft:" + identifier;
            return AllSet.Contains(identifier);
        }
    }

